//    neu = mix(neu,sun/q11,clamp01(q11 * 18.0))*(bdist+.2)*(2.0 + sin(vec3(arg * 2.0, arg * 3.0,5.0 * arg)));
ret1 = max(ret1 * 1.0,neu) ;
n++;
}
//ret = vec3( 1.0 ) - exp(-ret1 / 2.0/(audioLow*.1+1*rad)+.1);
ret = vec3( 1.0 ) - exp(-ret1/(.2/audioLow+rad)/audioLow*.5+.1);
//ret = GetPixel(uv+.5).r;
//ret = sun;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  float arg;
vec2 uv1, uv2, uv3, uv4;
vec3 ret1, neu, blur, sun;
shader_body
{
float ang2, c, s;
uv -= .5;
uv *= uAspect.xy;
uv2 = vec2(1.0 / rad+uTime / 2.0, ang * 2.0/3.14);
float z = abs(.5/uv.y);
uv2 = vec2(z*uv.x, z+uTime / 2.0);
vec2 noise = (texture(sampler_noise_hq,uv2)-.5)/z * 2.0;
//uv += rad*rad * noise*.02;
float dist = 1;
float bdist = 1;
float inten = 1;
ret1 = 0;
int anz = 1;
float n = 1;
while (n <= anz) {
ang2 = n/anz*3.14+q9;
c = cos(ang2);
s = sin(ang2);
uv2.x =  uv.x*c - uv.y*s;
uv2.y =  uv.x*s + uv.y*c;
uv2 *= uAspect.yx;
uv3 = fract(1.0 * uv2*dist + .5 );;
uv3=abs(fract(uv3+.5)-.5) +rad*rad * noise*.02*audioLowSmooth;;
bdist = (1.0 - GetBlur2(uv3).b);
uv4 = multiply(uv3,mat2(cos(q31),sin(q31), -sin(q31), cos(q31))),
sun = .04/length(sin(uv4.x*audioLowSmooth+1.5+bdist+ noise*.04*audioLowSmooth))*bdist;
arg = bdist + q6;
neu =  mix(GetPixel (uv3).r,GetBlur1(uv3).r,clamp01(q11 * 8.0)*1.1) ;
neu = max(neu,sun)*(bdist+.2)*(2.0 + sin(vec3(arg * 2.0, arg * 3.0,5.0 * arg)));
//    neu = mix(neu,sun/q11,clamp01(q11 * 18.0))*(bdist+.2)*(2.0 + sin(vec3(arg * 2.0, arg * 3.0,5.0 * arg)));
ret1 = max(ret1 * 1.0,neu) ;
n++;
}
//ret = vec3( 1.0 ) - exp(-ret1 / 2.0/(audioLow*.1+1*rad)+.1);
ret = vec3( 1.0 ) - exp(-ret1/(.2/audioLow+rad)/audioLow*.5+.1);
//ret = GetPixel(uv+.5).r;
//ret = sun;
}
  fragColor = vec4(ret, 1.0);
}

